Compute active algorithm:
```ts
const SECTION_SCROLL_OFFSET = 24
function updateActiveFromScroll(): void {
  if (!scrollContainer) return
  const containerTop = scrollContainer.getBoundingClientRect?.().top ?? 0
  const scrollTop = scrollContainer.scrollTop
  const atBottom = scrollContainer.scrollHeight > 0 && scrollTop + scrollContainer.clientHeight >= scrollContainer.scrollHeight - 2
  let next: SectionKey = 'account'
  if (atBottom) { next = 'about' } else {
    for (const {key} of sections) {
      const el = getSectionElement(key)
      if (!el) continue
      const top = el.getBoundingClientRect().top - containerTop
      if (top <= SECTION_SCROLL_OFFSET) next = key
    }
  }
  active.value = next
}
```
