import { computed, reactive, ref, watch } from 'vue'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { authApi } from '@/api/auth'

const props = defineProps<{ modelValue: boolean }>()
const emit = defineEmits<{ 'update:modelValue': [value: boolean]; success: [] }>()

const formRef = ref<FormInstance>()
const submitting = ref(false)
const errorText = ref('')

const form = reactive({ currentPassword: '', newPassword: '', confirmPassword: '' })

const rules = computed<FormRules>(() => ({
  currentPassword: [{ required: true, message: '请输入旧密码', trigger: 'blur' }],
  newPassword: [
    { required: true, message: '请输入新密码', trigger: 'blur' },
    { min: 8, message: '新密码至少 8 位', trigger: 'blur' },
    {
      validator: (_rule, value: string, callback) => {
        if (value && value === form.currentPassword) callback(new Error('新密码不能与旧密码相同'))
        else callback()
      },
      trigger: 'blur',
    },
  ],
  confirmPassword: [
    { required: true, message: '请再次输入新密码', trigger: 'blur' },
    {
      validator: (_rule, value: string, callback) => {
        if (value !== form.newPassword) callback(new Error('两次输入的新密码不一致'))
        else callback()
      },
      trigger: 'blur',
    },
  ],
}))

const visible = computed({
  get: () => props.modelValue,
  set: (value: boolean) => emit('update:modelValue', value),
})

function resetForm(): void {
  form.currentPassword = ''
  form.newPassword = ''
  form.confirmPassword = ''
  errorText.value = ''
  formRef.value?.clearValidate()
}

watch(
  () => props.modelValue,
  (open) => { if (open) { errorText.value = ''; formRef.value?.clearValidate() } },
)

async function submit(): Promise<void> {
  if (!formRef.value || submitting.value) return
  errorText.value = ''
  const valid = await formRef.value.validate().catch(() => false)
  if (!valid) return
  submitting.value = true
  try {
    await authApi.changePassword({
      current_password: form.currentPassword,
      new_password: form.newPassword,
    })
    ElMessage.success('密码已修改')
    emit('success')
    visible.value = false
    resetForm()
  } catch (cause) {
    errorText.value = cause instanceof Error ? cause.message : '修改密码失败，请稍后重试'
  } finally {
    submitting.value = false
  }
}

function close(): void {
  if (submitting.value) return
  visible.value = false
}
