{"content": "<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'

import { authApi } from '@/api/auth'

const props = defineProps<{
  modelValue: boolean
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
}>()

const formRef = ref<FormInstance>()
const submitting = ref(false)
const errorText = ref('')

const form = reactive({
  currentPassword: '',
  newPassword: '',
  confirmPassword: '',
})

const visible = computed({
  get: () => props.modelValue,
  set: (value: boolean) => emit('update:modelValue', value),
})

const rules = computed<FormRules>(() => ({
  currentPassword: [{ required: true, message: '请输入旧密码', trigger: 'blur' }],
  newPassword: [
    { required: true, message: '请输入新密码', trigger: 'blur' },
    { min: 8, message: '新密码至少 8 位', trigger: 'blur' },
    {
      validator: (_rule, value: string, callback) => {
        if (value && value === form.currentPassword) {
          callback(new Error('新密码不能与旧密码相同'))
          return
        }
        callback()
      },
      trigger: 'blur',
    },
  ],
  confirmPassword: [
    { required: true, message: '请再次输入新密码', trigger: 'blur' },
    {
      validator: (_rule, value: string, callback) => {
        if (value !== form.newPassword) {
          callback(new Error('两次输入的新密码不一致'))
          return
        }
        callback()
      },
      trigger: 'blur',
    },
  ],
}))

watch(
  () => props.modelValue,
  (open) => {
    if (!open) return
    errorText.value = ''
    formRef.value?.clearValidate()
  },
)

function resetForm(): void {
  form.currentPassword = ''
  form.newPassword = ''
  form.confirmPassword = ''
  errorText.value = ''
  formRef.value?.clearValidate()
}

function close(): void {
  if (submitting.value) return
  visible.value = false
}

async function submit(): Promise<void> {
  if (!formRef.value || submitting.value) return
  errorText.value = ''
  const valid = await formRef.value.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    await authApi.changePassword({
      current_password: form.currentPassword,
      new_password: form.newPassword,
    })
    ElMessage.success('密码已修改')
    visible.value = false
  } catch (cause) {
    errorText.value = cause instanceof Error ? cause.message : '修改密码失败，请稍后重试'
  } finally {
    submitting.value = false
  }
}
</script>

<template>
  <el-dialog
    v-model="visible"
    title="修改密码"
    width="min(440px, 92vw)"
    :close-on-click-modal="false"
    :close-on-press-escape="!submitting"
    :show-close="!submitting"
    @closed="resetForm"
  >
    <el-form
      ref="formRef"
      :model="form"
      :rules="rules"
      label-position="top"
      @submit.prevent="submit"
    >
      <el-form-item label="旧密码" prop="currentPassword">
        <el-input
          v-model="form.currentPassword"
          type="password"
          name="current_password"
          autocomplete="current-password"
          placeholder="输入当前使用的密码"
          show-password
        />
      </el-form-item>

      <el-form-item label="新密码" prop="newPassword">
        <el-input
          v-model="form.newPassword"
          type="password"
          name="new_password"
          autocomplete="new-password"
          placeholder="至少 8 位，且不能与旧密码相同"
          show-password
        />
      </el-form-item>

      <el-form-item label="确认新密码" prop="confirmPassword">
        <el-input
          v-model="form.confirmPassword"
          type="password"
          name="confirm_password"
          autocomplete="new-password"
          placeholder="再次输入新密码"
          show-password
        />
      </el-form-item>

      <p v-if="errorText" class="form-error" role="alert">{{ errorText }}</p>

      <div class="dialog-actions">
        <button type="button" class="btn" :disabled="submitting" @click="close">取消</button>
        <button
          type="button"
          class="btn primary"
          data-testid="submit-password"
          :disabled="submitting"
          @click="submit"
        >
          {{ submitting ? '提交中…' : '确认修改' }}
        </button>
      </div>
    </el-form>
  </el-dialog>
</template>

<style scoped>
.form-error {
  margin-bottom: 12px;
  padding: 8px 10px;
  border: 1px solid var(--red-soft, #f3c9c4);
  border-radius: 6px;
  background: var(--red-bg, #fdf1ef);
  color: var(--red, #b3261e);
  font-size: 11.5px;
  line-height: 1.6;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 4px;
}
</style>
