                <button type="button" class="link danger" @click="logout">退出登录</button>
              </div>
            </header>
            <dl class="kv">
              <div>
                <dt>展示名</dt>
                <dd>{{ auth.user?.display_name ?? '—' }}</dd>
              </div>
              <div>
